class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { sheetOpen: false };
    this.labelRef = React.createRef();
  }
  renderVals() {
    return {
      labelRef: this.labelRef,
      sheetOpen: this.state.sheetOpen,
      showReadingTime: this.props.showReadingTime ?? true,
      jumpBarPos: (this.props.stickyJumpBar ?? true) ? "sticky" : "relative",
      openSheet: () => this.setState({ sheetOpen: true }),
      closeSheet: () => this.setState({ sheetOpen: false })
    };
  }
  componentDidMount() {
    const frame = document.querySelector("[data-frame='m1']");
    if (!frame) return;
    const secs = Array.from(frame.querySelectorAll("[data-sec]"));
    if (!secs.length) return;
    let current = null;
    const pick = () => {
      const top = frame.getBoundingClientRect().top;
      let label = secs[0].getAttribute("data-sec");
      for (const s of secs) {
        if (s.getBoundingClientRect().top - top <= 92) label = s.getAttribute("data-sec");
        else break;
      }
      if (label !== current) {
        current = label;
        if (this.labelRef.current) this.labelRef.current.textContent = label;
      }
    };
    let lastTop = null;
    const poll = () => {
      const t = frame.scrollTop;
      if (t !== lastTop) { lastTop = t; pick(); }
    };
    this._poll = setInterval(poll, 150);
    this._onScroll = poll;
    frame.addEventListener("scroll", poll, { passive: true });
    pick();
    this._frame = frame;
  }
  componentWillUnmount() {
    if (this._poll) clearInterval(this._poll);
    if (this._frame) this._frame.removeEventListener("scroll", this._onScroll);
  }
}
